import json,os
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in __import__('re').finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def transform(g):
    H,W=len(g),len(g[0])
    colc={}; rowc={}; block=set()
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v in (0,3): continue
            colc[c]=v; rowc[r]=v
    # pure-3 plus = blocker: 3 with vertical arms above/below and horizontal arms left/right, empty center
    for r in range(1,H-1):
        for c in range(1,W-1):
            if g[r][c]==0 and g[r-1][c]==3 and g[r+1][c]==3 and g[r][c-1]==3 and g[r][c+1]==3:
                block.add(c)
    out=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if g[r][c]==3: out[r][c]=3
            elif c in block: out[r][c]=0
            elif c in colc: out[r][c]=colc[c]
            elif r in rowc: out[r][c]=rowc[r]
    return out
