def transform(g):
    H,W=len(g),len(g[0])
    pluses=[]  # (r,c,color)
    for r in range(1,H-1):
        for c in range(1,W-1):
            if g[r][c]!=3 and g[r-1][c]==3 and g[r+1][c]==3 and g[r][c-1]==3 and g[r][c+1]==3:
                pluses.append((r,c,g[r][c]))
    out=[[0]*W for _ in range(H)]
    def extent(fixed, along, centers, horiz):
        # returns L,R inclusive along 'along' axis
        L,R=0,(W if horiz else H)-1
        for (pr,pc,col) in pluses:
            if (pr,pc)==(fixed and 0,0): pass
            if (pr,pc)==centers: continue
            if horiz:
                if pr-1<=fixed<=pr+1:  # plus bbox rows contain this row
                    if pc+1<along: L=max(L,pc-1)  # bbox right edge
                    if pc-1>along: R=min(R,pc+1)  # bbox left edge
            else:
                if pc-1<=fixed<=pc+1:
                    if pr+1<along: L=max(L,pr-1)
                    if pr-1>along: R=min(R,pr+1)
        return L,R
    rowfill={}; colfill={}
    for (r,c,col) in pluses:
        L,R=extent(r,c,(r,c),True); rowfill[r]=(col,L,R)
        L,R=extent(c,r,(r,c),False); colfill[c]=(col,L,R)
    for r in range(H):
        for c in range(W):
            if g[r][c]==3: out[r][c]=3; continue
            if c in colfill:
                col,L,R=colfill[c]
                if L<=r<=R: out[r][c]=col; continue
            if r in rowfill:
                col,L,R=rowfill[r]
                if L<=c<=R: out[r][c]=col
    return out
